#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MyDesk v306 適用（見積Excel: 依頼シートのテンプレDL＋取込を1メニューに）
使い方: dashboard.jsx と同じフォルダで  python3 apply_v306_dashboard.py"""
import gzip, base64, json, sys, os
PATH="dashboard.jsx"
if not os.path.exists(PATH):
    print("❌ dashboard.jsx が見つかりません。同じフォルダで実行してください。"); sys.exit(1)
PAIRS=json.loads('[["H4sIADHca2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zWy0C0zNjDVLSzNL0nVzU6tzEss000vyi8tSCrNydbNzC3ILypRslbQ11d43Dz5cfPqx82dL9bOeNqx9OnaCQBDezN7WwAAAA==", "H4sIADHca2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zWy1C0zNjDTLSzNL0nVLUnNLchJBDJScpSsFfT1FR43T37cvPpxc+eLtTOedix9unYCAF630cZPAAAA"], ["H4sIADHca2oC/7MJS81LyS8KLM0vSXVOLEpRyE6ttK0uLNPLTKlVKCwDMWsVivLLi22rQWStQllRarJtdRlYV7FeWmZeikaZrV1wSVFmXroGSJumra0tlAs0BqLQM0VTsxYAQHxG/GsAAAA=", "H4sIADHca2oC/7MJS81LyS8KLM0vSXVOLEpRyE6ttK0uLNPLTKlVKCwDMWsVivLLi22rQWStQnFJflEqkFegB2HVKpQVpSbbVpeBzSnWS8vMS9Eos7ULLinKzEvXABmkaWtrC+UCDYYo9EzR1KwFACOksAB9AAAA"], ["", ""]]')
def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")
raw=open(PATH,"rb").read(); had_crlf=b"\r\n" in raw
text=raw.replace(b"\r\n",b"\n").decode("utf-8")
applied=skipped=0
for eo,en in PAIRS:
    old,new=dec(eo),dec(en)
    if text.count(new)>=1: skipped+=1; continue
    c=text.count(old)
    if c==0:
        print("❌ 対象が見つかりません（現在のビルドを確認）:"); print("   "+old[:80].replace("\n"," / ")); print("   grep MYDESK_BUILD dashboard.jsx"); sys.exit(1)
    if c!=1:
        print("❌ 対象が%d箇所（1箇所想定）"%c); sys.exit(1)
    text=text.replace(old,new,1); applied+=1
out=text.replace("\n","\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH,"wb").write(out)
print("✅ v306 適用完了 (適用 %d / スキップ %d)"%(applied,skipped))
print("   ビルド: 2026-07-29-v306-quote-template-dl")
